const PANEL  = 'rgba(17,20,26,0.95)';
const HAIR   = '#2E353D';
const MUTED  = '#8B96A3';

const MONO = "'IBM Plex Mono', ui-monospace, SFMono-Regular, Menlo, monospace";
const SANS = "'Barlow Condensed', 'Oswald', 'Inter', -apple-system, sans-serif";
const BODY = "'Inter', -apple-system, 'Segoe UI', sans-serif";
/* The plan itself is set in a geometric sans, matching the reference: circular
   bowls and a tall x-height stay legible at the small sizes map labels need. */
const MAPFONT = "'Poppins', 'Inter', -apple-system, sans-serif";

/* zoom limits, in metres of visible width */
const MIN_SPAN = 14;
const MAX_SPAN = LAYOUT.meta.w * 1.6;
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));

/* ---------- geometry helpers ---------- */
function pathWithHoles(pts, holes) {
  const ring = (r) => `M${r.map((p) => `${p[0]} ${p[1]}`).join('L')}Z`;
  return [ring(pts), ...(holes || []).map(ring)].join(' ');
}

function centroid(pts) {
  let a = 0, x = 0, y = 0;
  for (let i = 0; i < pts.length; i++) {
    const [x0, y0] = pts[i];
    const [x1, y1] = pts[(i + 1) % pts.length];
    const f = x0 * y1 - x1 * y0;
    a += f; x += (x0 + x1) * f; y += (y0 + y1) * f;
  }
  if (Math.abs(a) < 1e-9) {
    const n = pts.length;
    return [pts.reduce((s, p) => s + p[0], 0) / n, pts.reduce((s, p) => s + p[1], 0) / n];
  }
  a *= 0.5;
  return [x / (6 * a), y / (6 * a)];
}

/** outward-facing normal of edge p1->p2, away from the plot centre */
function outwardNormal(p1, p2, c) {
  let nx = -(p2[1] - p1[1]);
  let ny = p2[0] - p1[0];
  const len = Math.hypot(nx, ny) || 1;
  nx /= len; ny /= len;
  const mx = (p1[0] + p2[0]) / 2, my = (p1[1] + p2[1]) / 2;
  if (nx * (c[0] - mx) + ny * (c[1] - my) > 0) { nx = -nx; ny = -ny; }
  return [nx, ny];
}

/** "9 Meter Wide Road" rather than the CAD's "9 MT. WIDE ROAD" */
function roadLabelText(r) {
  const t = r.text.toUpperCase();
  if (t.includes('HIGHWAY')) return `${r.w} Meter Wide State Highway (SH-347)`;
  if (t.includes('SERVICE')) return `${r.w} Meter Wide Service Road`;
  return `${r.w} Meter Wide Road`;
}

/**
 * How large a plot number can be drawn before it overruns the plot edge.
 * `ir` is the radius of the largest circle fitting inside the plot; an
 * n-digit number occupies roughly 0.58n by 0.70 per unit of font size.
 */
function fittedNumberSize(plot, preferred) {
  const budget = plot.ir / Math.hypot(0.29 * plot.name.length, 0.35);
  return Math.min(preferred, budget);
}

/* ---------- derived once, at module load ---------- */
const META = LAYOUT.meta;
const FEATURES = LAYOUT.features.map((f, i) => ({ ...f, i, c: centroid(f.pts) }));
const PLOTS = FEATURES.filter((f) => f.kind === 'plot');
const BY_NAME = new Map(PLOTS.map((f) => [f.name, f]));
const DRAW_ORDER = { road: 0, htl: 1, open_space: 2, amenity: 3, utility: 4, plot: 5 };
const SORTED = [...FEATURES].sort((a, b) => DRAW_ORDER[a.kind] - DRAW_ORDER[b.kind]);
const AREA_MIN = Math.min(...PLOTS.map((p) => p.area));
const AREA_MAX = Math.max(...PLOTS.map((p) => p.area));

/* ---------- UI atoms ---------- */
const Eyebrow = ({ children, style }) => (
  <div style={{ fontFamily: SANS, fontSize: 11, letterSpacing: '0.18em', textTransform: 'uppercase',
    color: MUTED, fontWeight: 600, ...style }}>{children}</div>
);

function Chip({ active, onClick, children, swatch }) {
  return (
    <button
      onClick={onClick}
      style={{
        display: 'inline-flex', alignItems: 'center', gap: 6,
        padding: '6px 11px', borderRadius: 999, cursor: 'pointer',
        border: `1px solid ${active ? ACCENT : HAIR}`,
        background: active ? 'rgba(201,169,119,0.14)' : 'transparent',
        color: active ? ACCENT : '#B7C0CA',
        fontFamily: SANS, fontSize: 13, letterSpacing: '0.06em', textTransform: 'uppercase',
        fontWeight: 600, whiteSpace: 'nowrap', WebkitTapHighlightColor: 'transparent',
        touchAction: 'manipulation',
      }}
    >
      {swatch && <span style={{ width: 9, height: 9, borderRadius: 2, background: swatch }} />}
      {children}
    </button>
  );
}

/* ---------------------------------------------------------------
   Dimension overlay for the selected plot.

   CAD fillets arrive as a run of ~0.3 m chords, so a naive one-line-per-edge
   overlay draws thirty dimension lines around a single rounded corner. Edges
   are therefore grouped first: anything shorter than SHORT_EDGE is part of a
   curve, consecutive curve chords collapse into one run, and that run is
   dimensioned as a single offset arc carrying its total length.
--------------------------------------------------------------- */
const SHORT_EDGE = 1.0;     // metres — below this an edge is a chord, not a side
const MIN_RUN = 0.6;        // runs shorter than this aren't worth dimensioning

/** group the boundary into straight sides and curved runs */
function buildRuns(pts, sides, c) {
  const n = pts.length;
  const segs = pts.map((p1, i) => ({
    p1, p2: pts[(i + 1) % n], len: sides[i],
    nrm: outwardNormal(p1, pts[(i + 1) % n], c),
  }));

  const runs = [];
  let curve = null;
  segs.forEach((s) => {
    if (s.len >= SHORT_EDGE) {
      if (curve) { runs.push(curve); curve = null; }
      runs.push({ curved: false, segs: [s], len: s.len });
    } else {
      if (!curve) curve = { curved: true, segs: [], len: 0 };
      curve.segs.push(s);
      curve.len += s.len;
    }
  });
  if (curve) runs.push(curve);

  // a corner arc can straddle the start of the ring — stitch those halves
  if (runs.length > 1 && runs[0].curved && runs[runs.length - 1].curved) {
    const tail = runs.pop();
    runs[0] = { curved: true, segs: [...tail.segs, ...runs[0].segs], len: tail.len + runs[0].len };
  }
  return runs.filter((r) => r.len >= MIN_RUN);
}

/** offset a run outward, mitring at each interior vertex so the gap stays even */
function offsetRun(run, off) {
  const poly = [run.segs[0].p1, ...run.segs.map((s) => s.p2)];
  const nrm = run.segs.map((s) => s.nrm);
  return poly.map((p, i) => {
    const a = nrm[Math.max(0, i - 1)];
    const b = nrm[Math.min(nrm.length - 1, i)];
    let nx = a[0] + b[0], ny = a[1] + b[1];
    const L = Math.hypot(nx, ny) || 1;
    nx /= L; ny /= L;
    const cosHalf = Math.max(0.4, a[0] * nx + a[1] * ny);   // don't let sharp corners fly out
    const d = off / cosHalf;
    return [p[0] + nx * d, p[1] + ny * d];
  });
}

/** point, tangent and normal at the halfway mark along a polyline */
function midOfPolyline(poly) {
  let total = 0;
  const seg = [];
  for (let i = 0; i < poly.length - 1; i++) {
    const l = Math.hypot(poly[i + 1][0] - poly[i][0], poly[i + 1][1] - poly[i][1]);
    seg.push(l); total += l;
  }
  let want = total / 2, i = 0;
  while (i < seg.length - 1 && want > seg[i]) { want -= seg[i]; i++; }
  const t = seg[i] ? want / seg[i] : 0;
  const a = poly[i], b = poly[i + 1] || poly[i];
  const dx = b[0] - a[0], dy = b[1] - a[1];
  const L = Math.hypot(dx, dy) || 1;
  return {
    p: [a[0] + dx * t, a[1] + dy * t],
    tan: [dx / L, dy / L],
    total,
  };
}

function DimensionOverlay({ plot }) {
  const c = centroid(plot.pts);
  const ir = plot.ir;

  /* Measured off the reference: the dimension text and its stand-off are
     fixed distances on the ground (~0.38 m and ~0.50 m) rather than fractions
     of the plot, so every plot's dimensions read at the same weight. Only the
     identity block scales with the parcel. */
  const off = 0.50 + ir * 0.02;
  const txt = 0.38;
  const tick = txt * 0.8;
  const hair = 0.045;

  /* Identity block proportions taken from the reference: a dominant number,
     the metric area as a quiet secondary line, then the imperial figure back
     up in weight — that is the one a buyer actually quotes. */
  const num = Math.min(ir * 0.27, 3.4);
  const sqm = num * 0.32;
  const sqft = num * 0.51;

  const runs = buildRuns(plot.pts, plot.sides, c);

  return (
    <g style={{ pointerEvents: 'none' }}>
      {runs.map((run, ri) => {
        const poly = offsetRun(run, off);
        const first = run.segs[0];
        const last = run.segs[run.segs.length - 1];
        const a = poly[0];
        const b = poly[poly.length - 1];
        const { p: mid, tan } = midOfPolyline(poly);

        // ticks sit square across the line, at whatever angle it ends
        const t0 = [poly[1][0] - poly[0][0], poly[1][1] - poly[0][1]];
        const t1 = [b[0] - poly[poly.length - 2][0], b[1] - poly[poly.length - 2][1]];
        const perp = (t) => {
          const L = Math.hypot(t[0], t[1]) || 1;
          return [(-t[1] / L) * tick, (t[0] / L) * tick];
        };
        const k0 = perp(t0), k1 = perp(t1);

        let deg = (Math.atan2(tan[1], tan[0]) * 180) / Math.PI;
        if (deg > 90) deg -= 180;
        if (deg < -90) deg += 180;

        // push the figure clear of the line, on the outward side
        const mn = [-tan[1], tan[0]];
        const away = (mn[0] * (mid[0] - c[0]) + mn[1] * (mid[1] - c[1])) > 0 ? 1 : -1;
        const lx = mid[0] + mn[0] * away * txt * 0.85;
        const ly = mid[1] + mn[1] * away * txt * 0.85;

        const d = `M${poly.map((p) => `${p[0]} ${p[1]}`).join('L')}`;

        return (
          <g key={`run${ri}`}>
            <line x1={first.p1[0]} y1={first.p1[1]} x2={a[0]} y2={a[1]}
              stroke="#FFFFFF" strokeWidth={hair}
              strokeDasharray={`${hair * 4} ${hair * 3}`} opacity="0.7" />
            <line x1={last.p2[0]} y1={last.p2[1]} x2={b[0]} y2={b[1]}
              stroke="#FFFFFF" strokeWidth={hair}
              strokeDasharray={`${hair * 4} ${hair * 3}`} opacity="0.7" />

            <path d={d} fill="none" stroke="#FFFFFF" strokeWidth={hair}
              strokeDasharray={`${hair * 5} ${hair * 3}`} opacity="0.9"
              strokeLinejoin="round" strokeLinecap="round" />

            <line x1={a[0] - k0[0]} y1={a[1] - k0[1]} x2={a[0] + k0[0]} y2={a[1] + k0[1]}
              stroke="#FFFFFF" strokeWidth={hair * 1.4} />
            <line x1={b[0] - k1[0]} y1={b[1] - k1[1]} x2={b[0] + k1[0]} y2={b[1] + k1[1]}
              stroke="#FFFFFF" strokeWidth={hair * 1.4} />

            <text x={lx} y={ly} transform={`rotate(${deg} ${lx} ${ly})`}
              textAnchor="middle" dy="0.35em"
              fontFamily={MAPFONT} fontSize={txt} fontWeight="500" fill="#FFFFFF">
              {run.len.toFixed(2)} m
            </text>
          </g>
        );
      })}

      <text x={c[0]} y={c[1] - num * 0.60} textAnchor="middle" dy="0.35em"
        fontFamily={MAPFONT} fontSize={num} fontWeight="600"
        letterSpacing={-num * 0.02} fill={SELECTED_INK}>{plot.name}</text>
      <text x={c[0]} y={c[1] + num * 0.52} textAnchor="middle" dy="0.35em"
        fontFamily={MAPFONT} fontSize={sqm} fontWeight="500" fill={SELECTED_INK} opacity="0.85">
        {plot.area.toFixed(2)} m²
      </text>
      <text x={c[0]} y={c[1] + num * 1.12} textAnchor="middle" dy="0.35em"
        fontFamily={MAPFONT} fontSize={sqft} fontWeight="600" fill={SELECTED_INK}>
        {(plot.area * SQFT).toLocaleString('en-IN', { maximumFractionDigits: 2 })} ft²
      </text>
    </g>
  );
}

/* ---------------------------------------------------------------
   Map.
   Input runs on Pointer Events, so mouse, touch and pen all take the
   same path: one pointer pans, two pinch-zoom about their midpoint,
   the wheel zooms about the cursor. On-screen buttons cover devices
   with neither a wheel nor multi-touch.
--------------------------------------------------------------- */
function PlanMap({ view, setView, selected, onSelect, matches, status, showNumbers }) {
  const svgRef = useRef(null);
  const pointers = useRef(new Map());
  const gesture = useRef(null);
  const moved = useRef(false);
  const [hover, setHover] = useState(null);

  const rect = () => svgRef.current.getBoundingClientRect();

  /* zoom about a point given as a fraction of the viewport */
  const zoomAbout = useCallback((factor, fx, fy) => {
    setView((v) => {
      const w = clamp(v.w * factor, MIN_SPAN, MAX_SPAN);
      const h = w * (v.h / v.w);
      return { x: v.x + (v.w - w) * fx, y: v.y + (v.h - h) * fy, w, h };
    });
  }, [setView]);

  /* wheel needs a non-passive listener to be able to preventDefault */
  useEffect(() => {
    const el = svgRef.current;
    if (!el) return;
    const onWheel = (e) => {
      e.preventDefault();
      const r = el.getBoundingClientRect();
      zoomAbout(e.deltaY > 0 ? 1.12 : 1 / 1.12,
        (e.clientX - r.left) / r.width, (e.clientY - r.top) / r.height);
    };
    el.addEventListener('wheel', onWheel, { passive: false });
    return () => el.removeEventListener('wheel', onWheel);
  }, [zoomAbout]);

  const onPointerDown = (e) => {
    pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
    moved.current = false;
    const ps = [...pointers.current.values()];
    if (ps.length === 1) {
      gesture.current = { mode: 'pan', sx: e.clientX, sy: e.clientY, view };
    } else if (ps.length === 2) {
      const [a, b] = ps;
      gesture.current = {
        mode: 'pinch', view,
        dist: Math.hypot(a.x - b.x, a.y - b.y) || 1,
        mx: (a.x + b.x) / 2, my: (a.y + b.y) / 2,
      };
    }
  };

  useEffect(() => {
    const onMove = (e) => {
      if (!pointers.current.has(e.pointerId)) return;
      pointers.current.set(e.pointerId, { x: e.clientX, y: e.clientY });
      const g = gesture.current;
      if (!g || !svgRef.current) return;
      const r = rect();
      const ps = [...pointers.current.values()];

      if (g.mode === 'pan' && ps.length === 1) {
        const px = e.clientX - g.sx, py = e.clientY - g.sy;
        if (Math.abs(px) > 4 || Math.abs(py) > 4) moved.current = true;
        setView({
          ...g.view,
          x: g.view.x - (px / r.width) * g.view.w,
          y: g.view.y - (py / r.height) * g.view.h,
        });
      } else if (g.mode === 'pinch' && ps.length >= 2) {
        const [a, b] = ps;
        const dist = Math.hypot(a.x - b.x, a.y - b.y) || 1;
        const w = clamp(g.view.w * (g.dist / dist), MIN_SPAN, MAX_SPAN);
        const h = w * (g.view.h / g.view.w);
        const fx = (g.mx - r.left) / r.width;
        const fy = (g.my - r.top) / r.height;
        moved.current = true;
        setView({ x: g.view.x + (g.view.w - w) * fx, y: g.view.y + (g.view.h - h) * fy, w, h });
      }
    };

    const onUp = (e) => {
      pointers.current.delete(e.pointerId);
      const ps = [...pointers.current.values()];
      if (ps.length === 1) {
        // second finger lifted — carry on panning from where the first one is
        gesture.current = { mode: 'pan', sx: ps[0].x, sy: ps[0].y, view };
      } else if (ps.length === 0) {
        gesture.current = null;
      }
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
    return () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onUp);
    };
  }, [setView, view]);

  const zoom = META.w / view.w;
  const preferredNumberSize = Math.min(4.2, Math.max(1.4, 3.0 / Math.pow(zoom, 0.45)));
  const strokeW = 0.35 / Math.sqrt(zoom);
  const selFeature = selected ? BY_NAME.get(selected) : null;

  const zoomBtn = {
    width: 40, height: 40, borderRadius: 10, cursor: 'pointer',
    background: PANEL, border: `1px solid ${HAIR}`, color: '#D7DCE2',
    fontFamily: BODY, fontSize: 19, fontWeight: 600, lineHeight: 1,
    display: 'flex', alignItems: 'center', justifyContent: 'center',
    WebkitTapHighlightColor: 'transparent', touchAction: 'manipulation',
  };

  return (
    <>
      <svg
        ref={svgRef}
        viewBox={`${view.x} ${view.y} ${view.w} ${view.h}`}
        preserveAspectRatio="xMidYMid meet"
        onPointerDown={onPointerDown}
        onMouseLeave={() => setHover(null)}
        style={{ width: '100%', height: '100%', background: CANVAS, cursor: 'grab',
          display: 'block', touchAction: 'none', WebkitTapHighlightColor: 'transparent',
          WebkitUserSelect: 'none', userSelect: 'none' }}
      >
        <defs>
          <pattern id="chicholi-grid" width="20" height="20" patternUnits="userSpaceOnUse">
            <path d="M20 0H0V20" fill="none" stroke="#1E2229" strokeWidth="0.3" />
          </pattern>
        </defs>
        <rect x={-500} y={-500} width={META.w + 1000} height={META.h + 1000} fill="url(#chicholi-grid)" />

        {SORTED.map((f) => {
          const k = KIND[f.kind];
          const isPlot = f.kind === 'plot';
          const isSel = isPlot && selected === f.name;
          const dim = isPlot && matches && !matches.has(f.name);
          let fill = k.fill;
          if (isPlot) {
            const st = STATUS[status[f.name] || 'available'];
            fill = st.tones ? toneOf(f.name) : st.fill;
          }
          if (isSel) fill = SELECTED_FILL;
          return (
            <path
              key={f.i}
              d={pathWithHoles(f.pts, f.holes)}
              fill={fill}
              fillRule="evenodd"
              stroke={isSel ? SELECTED_EDGE : k.stroke}
              strokeWidth={isSel ? strokeW * 3.4 : strokeW}
              opacity={dim ? 0.22 : hover === f.name && isPlot ? 0.86 : 1}
              onMouseEnter={() => isPlot && setHover(f.name)}
              onClick={() => {
                if (moved.current || !isPlot) return;
                onSelect(f.name === selected ? null : f.name);
              }}
              style={{ cursor: isPlot ? 'pointer' : 'grab' }}
            />
          );
        })}

        {showNumbers && PLOTS.map((f) => {
          if (matches && !matches.has(f.name)) return null;
          if (f.name === selected) return null;      // the overlay draws this one
          const size = fittedNumberSize(f, preferredNumberSize);
          if (size < 0.9) return null;
          return (
            <text
              key={`n${f.i}`}
              x={f.lp[0]} y={f.lp[1]}
              textAnchor="middle" dy="0.35em"
              fontFamily={MAPFONT} fontSize={size} fontWeight="600" fill="#000000"
              style={{ pointerEvents: 'none' }}
            >{f.name}</text>
          );
        })}

        {selFeature && <DimensionOverlay plot={selFeature} />}

        {LAYOUT.roadLabels.map((r, i) => (
          <text
            key={`r${i}`}
            x={r.p[0]} y={r.p[1]}
            transform={`rotate(${r.a} ${r.p[0]} ${r.p[1]})`}
            textAnchor="middle" dy="0.35em"
            fontFamily={MAPFONT} fontSize={Math.max(1.5, 2.9 / Math.sqrt(zoom))}
            fontWeight="500" fill="#C9CED4"
            style={{ pointerEvents: 'none' }}
          >{roadLabelText(r)}</text>
        ))}

        {LAYOUT.areaLabels.map((a, i) => {
          const fs = Math.max(2.2, 4.2 / Math.sqrt(zoom));
          return (
            <g key={`a${i}`} style={{ pointerEvents: 'none' }}>
              <text x={a.p[0]} y={a.p[1] - fs * 0.35} textAnchor="middle" dy="0.35em"
                fontFamily={SANS} fontSize={fs} letterSpacing="0.14em"
                fill={KIND[a.kind].ink} fontWeight="600">{a.name}</text>
              <text x={a.p[0]} y={a.p[1] + fs * 0.85} textAnchor="middle" dy="0.35em"
                fontFamily={MONO} fontSize={fs * 0.62} fill={KIND[a.kind].ink} opacity="0.85">
                {a.area.toLocaleString('en-IN')} m²
              </text>
            </g>
          );
        })}
      </svg>

      {/* works where there is no wheel and no pinch */}
      <div className="zoom-pad" style={{ position: 'absolute', left: 14, bottom: 14, zIndex: 11,
        display: 'flex', flexDirection: 'column', gap: 8 }}>
        <button aria-label="Zoom in" style={zoomBtn} onClick={() => zoomAbout(1 / 1.35, 0.5, 0.5)}>+</button>
        <button aria-label="Zoom out" style={zoomBtn} onClick={() => zoomAbout(1.35, 0.5, 0.5)}>−</button>
      </div>
    </>
  );
}

/* ---------- detail panel ---------- */
function DetailPanel({ plot, status, setStatus, onClose, onQuote }) {
  if (!plot) return null;
  const sides = plot.sides;
  const st = status[plot.name] || 'available';

  const PANEL_LIGHT = 'rgba(255, 255, 255, 0.72)';
  const HAIR_LIGHT = 'rgba(20, 24, 32, 0.10)';
  const TEXT_MAIN = '#1C2230';
  const TEXT_MUTED = '#6B7280';
  const ACCENT_LIGHT = '#2C5A4F';
  const ACCENT_SOFT_BG = 'rgba(44, 90, 79, 0.08)';

  return (
    <>
      <style>{`
        @keyframes panelSlideInRight {
          from { transform: translateX(24px); opacity: 0; }
          to   { transform: translateX(0);    opacity: 1; }
        }
        @keyframes panelSlideUp {
          from { transform: translateY(20px); opacity: 0; }
          to   { transform: translateY(0);    opacity: 1; }
        }

        .plot-panel {
          position: absolute;
          top: 14px; right: 14px;
          width: 296px;
          max-height: calc(100% - 28px);
          overflow-y: auto;
          -webkit-overflow-scrolling: touch;
          background: rgba(255,255,255,0.9);
          border: 1px solid rgba(20,24,32,0.10);
          border-radius: 14px;
          padding: 20px;
          box-shadow:
            0 8px 30px rgba(20, 24, 32, 0.10),
            0 1px 2px rgba(20, 24, 32, 0.06),
            inset 0 1px 0 rgba(255,255,255,0.6);
          z-index: 12;
          box-sizing: border-box;
          animation: panelSlideInRight 0.28s cubic-bezier(0.16, 1, 0.3, 1);
        }
        /* frosted glass only where it is actually supported, so the panel
           never falls back to near-transparent and unreadable */
        @supports ((backdrop-filter: blur(1px)) or (-webkit-backdrop-filter: blur(1px))) {
          .plot-panel {
            background: rgba(255, 255, 255, 0.72);
            -webkit-backdrop-filter: blur(16px) saturate(140%);
            backdrop-filter: blur(16px) saturate(140%);
          }
        }

        .plot-panel .plot-name { font-size: 36px; }
        .plot-panel .stat-grid { grid-template-columns: 1fr 1fr; }
        .plot-panel .close-btn { transition: background 0.15s ease, color 0.15s ease; }
        .plot-panel .close-btn:hover { background: rgba(20,24,32,0.06); }
        .plot-panel .quote-btn { transition: filter 0.15s ease, transform 0.1s ease; }
        .plot-panel .quote-btn:hover { filter: brightness(1.08); }
        .plot-panel .quote-btn:active { transform: translateY(1px); }

        @media (max-width: 1024px) {
          .plot-panel { width: 262px; top: 12px; right: 12px; padding: 16px; }
          .plot-panel .plot-name { font-size: 30px; }
        }

        /* Phones: dock to the bottom edge as a wide, short sheet. The map
           keeps the whole upper area, and the selected plot is framed into
           it, so the panel can never cover what you just tapped. */
        @media (max-width: 640px) {
          .plot-panel {
            position: absolute;
            top: auto; left: 8px; right: 8px; bottom: 8px;
            width: auto; max-width: none;
            max-height: 38vh;
            border-radius: 16px;
            padding: 12px 14px calc(12px + env(safe-area-inset-bottom, 0px));
            box-shadow: 0 -6px 26px rgba(10, 14, 20, 0.28);
            animation: panelSlideUp 0.26s cubic-bezier(0.16, 1, 0.3, 1);
          }
          .plot-panel .plot-name { font-size: 24px; }
          .plot-panel .stat-grid {
            grid-template-columns: repeat(4, minmax(0, 1fr));
            gap: 6px; margin: 10px 0 10px;
          }
          .plot-panel .status-row { gap: 5px; margin-bottom: 10px; }
          .plot-panel .quote-btn { margin-top: 4px; padding: 11px; font-size: 12px; }
        }

        @media (max-width: 380px) {
          .plot-panel { padding: 10px 11px calc(10px + env(safe-area-inset-bottom, 0px)); }
          .plot-panel .plot-name { font-size: 20px; }
          .plot-panel .stat-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
        }

        /* short landscape phones: keep it out of the way entirely */
        @media (max-height: 460px) and (max-width: 900px) {
          .plot-panel { max-height: 52vh; }
        }
      `}</style>

      <div className="plot-panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
          <div>
            <div style={{ fontFamily: SANS, fontSize: 10, fontWeight: 600, letterSpacing: '0.14em',
              textTransform: 'uppercase', color: TEXT_MUTED, marginBottom: 4 }}>Plot</div>
            <div className="plot-name" style={{ fontFamily: MONO, fontWeight: 600,
              color: ACCENT_LIGHT, lineHeight: 1 }}>{plot.name}</div>
          </div>
          <button onClick={onClose} aria-label="Close plot details" className="close-btn"
            style={{ background: 'none', border: 'none', color: TEXT_MUTED, cursor: 'pointer',
              fontSize: 20, width: 34, height: 34, borderRadius: 8, display: 'flex',
              alignItems: 'center', justifyContent: 'center', flex: '0 0 auto',
              WebkitTapHighlightColor: 'transparent', touchAction: 'manipulation' }}>×</button>
        </div>

        <div className="stat-grid" style={{ display: 'grid', gap: 10, margin: '18px 0 14px' }}>
          {[
            { label: 'Area', value: plot.area.toLocaleString('en-IN'), unit: 'm²' },
            { label: 'Area', value: Math.round(plot.area * SQFT).toLocaleString('en-IN'), unit: 'sq ft' },
            { label: 'Frontage', value: Math.max(...sides).toFixed(2), unit: 'm' },
            { label: 'Perimeter', value: sides.reduce((s, v) => s + v, 0).toFixed(2), unit: 'm' },
          ].map((s, i) => (
            <div key={i} style={{ background: ACCENT_SOFT_BG, border: `1px solid ${HAIR_LIGHT}`,
              borderRadius: 10, padding: '9px 11px', minWidth: 0 }}>
              <div style={{ fontFamily: SANS, fontSize: 9, fontWeight: 600, letterSpacing: '0.08em',
                textTransform: 'uppercase', color: TEXT_MUTED, marginBottom: 3 }}>{s.label}</div>
              <div style={{ fontFamily: MONO, fontSize: 15, fontWeight: 600, color: TEXT_MAIN,
                whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {s.value}
                <span style={{ fontSize: 10, color: TEXT_MUTED, fontWeight: 500, marginLeft: 4 }}>{s.unit}</span>
              </div>
            </div>
          ))}
        </div>

        <div style={{ fontFamily: SANS, fontSize: 10, fontWeight: 600, letterSpacing: '0.14em',
          textTransform: 'uppercase', color: TEXT_MUTED, marginBottom: 8 }}>Status</div>
        <div className="status-row" style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
          {Object.entries(STATUS).map(([key, s]) => {
            const active = st === key;
            return (
              <button key={key} onClick={() => setStatus(plot.name, key)}
                style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '7px 11px',
                  borderRadius: 999, border: `1px solid ${active ? ACCENT_LIGHT : HAIR_LIGHT}`,
                  background: active ? ACCENT_SOFT_BG : 'rgba(255,255,255,0.5)',
                  color: active ? ACCENT_LIGHT : TEXT_MUTED, fontFamily: SANS, fontSize: 11,
                  fontWeight: 600, cursor: 'pointer', transition: 'all 0.15s ease',
                  WebkitTapHighlightColor: 'transparent', touchAction: 'manipulation' }}>
                <span style={{ width: 6, height: 6, borderRadius: '50%', background: s.dot }} />
                {s.label}
              </button>
            );
          })}
        </div>

        <button onClick={onQuote} className="quote-btn"
          style={{ width: '100%', padding: '12px', background: ACCENT_LIGHT, border: 'none',
            borderRadius: 9, color: '#FFFFFF', fontFamily: SANS, fontSize: 13, fontWeight: 700,
            letterSpacing: '0.08em', textTransform: 'uppercase', cursor: 'pointer',
            boxShadow: '0 4px 12px rgba(44, 90, 79, 0.25)',
            WebkitTapHighlightColor: 'transparent', touchAction: 'manipulation' }}>
          Build quotation
        </button>
      </div>
    </>
  );
}

/* ---------- quotation ---------- */
function Quotation({ plot, onClose, onSave }) {
  const areaSqft = Math.round(plot.area * SQFT);
  const [f, setF] = useState({ name: '', phone: '', rate: 2900, downPct: 20, reg: 0, months: 12 });
  const [saved, setSaved] = useState(false);
  const set = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }));

  const total = Math.round(areaSqft * (parseFloat(f.rate) || 0));
  const down = Math.round(total * ((parseFloat(f.downPct) || 0) / 100));
  const reg = parseFloat(f.reg) || 0;
  const balance = total - down - reg;
  const months = Math.max(1, parseInt(f.months, 10) || 1);
  const emi = Math.round(balance / months);
  const inr = (n) => `₹${Math.round(n).toLocaleString('en-IN')}`;

  const save = async () => {
    const ok = await onSave({ plot: plot.name, area: areaSqft, ...f, total, down, balance, emi });
    if (ok) { setSaved(true); setTimeout(() => setSaved(false), 1600); }
  };

  const field = {
    width: '100%', padding: '9px 10px', background: '#0D1117', color: '#EFEAE0',
    border: `1px solid ${HAIR}`, borderRadius: 7, fontFamily: MONO, fontSize: 16,
    outline: 'none', boxSizing: 'border-box',   // 16px keeps iOS from zooming on focus
  };

  return (
    <div onClick={onClose} style={{ position: 'fixed', inset: 0, background: 'rgba(8,11,15,0.78)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16, zIndex: 40 }}>
      <div onClick={(e) => e.stopPropagation()} style={{ width: '100%', maxWidth: 520, background: PANEL,
        border: `1px solid ${HAIR}`, borderRadius: 14, padding: 20, maxHeight: '88vh',
        overflowY: 'auto', WebkitOverflowScrolling: 'touch', boxSizing: 'border-box' }}>
        <Eyebrow>Quotation</Eyebrow>
        <div style={{ fontFamily: SANS, fontSize: 24, color: ACCENT, fontWeight: 700,
          letterSpacing: '0.04em', marginBottom: 16 }}>
          PLOT {plot.name} · {areaSqft.toLocaleString('en-IN')} SQ FT
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(190px, 1fr))', gap: 10 }}>
          <div><Eyebrow style={{ marginBottom: 5 }}>Customer</Eyebrow><input style={field} value={f.name} onChange={set('name')} placeholder="Full name" /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Phone</Eyebrow><input style={field} value={f.phone} onChange={set('phone')} inputMode="numeric" placeholder="10 digits" /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Rate / sq ft</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.rate} onChange={set('rate')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Down payment %</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.downPct} onChange={set('downPct')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Registry &amp; docs</Eyebrow><input style={field} type="number" inputMode="decimal" value={f.reg} onChange={set('reg')} /></div>
          <div><Eyebrow style={{ marginBottom: 5 }}>Instalments (months)</Eyebrow><input style={field} type="number" inputMode="numeric" value={f.months} onChange={set('months')} /></div>
        </div>

        <div style={{ marginTop: 18, borderTop: `1px solid ${HAIR}` }}>
          {[['Total consideration', inr(total)], ['Down payment', inr(down)],
            ['Registry & documentation', inr(reg)], ['Balance', inr(balance)],
            [`Monthly instalment × ${months}`, inr(emi)]].map(([l, v], i, arr) => (
            <div key={l} style={{ display: 'flex', justifyContent: 'space-between', gap: 12,
              padding: '9px 0', borderBottom: i < arr.length - 1 ? `1px solid ${HAIR}` : 'none',
              fontFamily: MONO, fontSize: i === 0 || i === arr.length - 1 ? 14 : 13,
              color: i === 0 ? ACCENT : i === arr.length - 1 ? '#8CC98F' : '#D5DBE2',
              fontWeight: i === 0 || i === arr.length - 1 ? 700 : 500 }}>
              <span>{l}</span><span>{v}</span>
            </div>
          ))}
        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 18, flexWrap: 'wrap' }}>
          <button onClick={save} style={{ flex: '1 1 180px', padding: 13, borderRadius: 8, border: 'none',
            background: saved ? '#7CBA81' : ACCENT, color: '#141820', fontFamily: SANS, fontWeight: 700,
            letterSpacing: '0.1em', textTransform: 'uppercase', fontSize: 14, cursor: 'pointer',
            touchAction: 'manipulation' }}>
            {saved ? 'Saved' : 'Save quotation'}
          </button>
          <button onClick={onClose} style={{ flex: '0 1 120px', padding: '13px 20px', borderRadius: 8,
            background: 'transparent', border: `1px solid ${HAIR}`, color: '#B7C0CA', fontFamily: SANS,
            fontSize: 14, letterSpacing: '0.08em', textTransform: 'uppercase', cursor: 'pointer',
            touchAction: 'manipulation' }}>Close</button>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------
   Persistence — the only part tied to the browser.
   Swap these for your Firestore calls; nothing else changes.
--------------------------------------------------------------- */
const STORE_KEY = 'chicholi:status';
const hasArtifactStore = () => typeof window !== 'undefined' && !!window.storage;

async function readKey(key, shared) {
  if (hasArtifactStore()) {
    const res = await window.storage.get(key, shared);
    return res && res.value ? res.value : null;
  }
  return window.localStorage.getItem(key);
}

async function writeKey(key, value, shared) {
  if (hasArtifactStore()) {
    await window.storage.set(key, value, shared);
    return true;
  }
  window.localStorage.setItem(key, value);
  return true;
}

async function loadStatus() {
  try {
    const raw = await readKey(STORE_KEY, true);
    return raw ? JSON.parse(raw) : {};
  } catch (e) { return {}; }
}

async function saveStatus(map) {
  try { return await writeKey(STORE_KEY, JSON.stringify(map), true); }
  catch (e) { return false; }
}

async function saveQuotation(record) {
  try {
    return await writeKey(`chicholi:quote:${record.plot}:${Date.now()}`, JSON.stringify(record), false);
  } catch (e) { return false; }
}

/* ---------- app ---------- */
export default function ChicholiMasterPlan() {
  const wrapRef = useRef(null);
  const [box, setBox] = useState({ w: 1200, h: 700 });
  const [view, setView] = useState({ x: -12, y: -12, w: META.w + 24, h: META.h + 24 });
  const [selected, setSelected] = useState(null);
  const [quote, setQuote] = useState(null);
  const [status, setStatusMap] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [search, setSearch] = useState('');
  const [minA, setMinA] = useState('');
  const [maxA, setMaxA] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [showNumbers, setShowNumbers] = useState(true);

  /* the map must fill the device, not a fixed 100vh that mobile browser
     chrome then eats into */
  useEffect(() => {
    let meta = document.querySelector('meta[name="viewport"]');
    if (!meta) {
      meta = document.createElement('meta');
      meta.setAttribute('name', 'viewport');
      document.head.appendChild(meta);
    }
    meta.setAttribute('content',
      'width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover');
  }, []);

  /* track the drawing area so the viewBox can match its aspect ratio —
     without this the plan letterboxes and zoom lands off-centre on any
     screen shaped differently from the layout */
  useEffect(() => {
    const el = wrapRef.current;
    if (!el) return;
    const read = () => {
      const r = el.getBoundingClientRect();
      if (r.width > 0 && r.height > 0) setBox({ w: r.width, h: r.height });
    };
    read();
    if (typeof ResizeObserver === 'undefined') {
      window.addEventListener('resize', read);
      window.addEventListener('orientationchange', read);
      return () => {
        window.removeEventListener('resize', read);
        window.removeEventListener('orientationchange', read);
      };
    }
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  const aspect = box.h / box.w;

  const fitView = useMemo(() => {
    const pad = 14;
    const w = Math.max(META.w + pad * 2, (META.h + pad * 2) / aspect);
    const h = w * aspect;
    return { x: META.w / 2 - w / 2, y: META.h / 2 - h / 2, w, h };
  }, [aspect]);

  /* keep the visible window matched to the container as it resizes or rotates */
  useEffect(() => {
    setView((v) => {
      const h = v.w * aspect;
      return { ...v, y: v.y + (v.h - h) / 2, h };
    });
  }, [aspect]);

  useEffect(() => { setView(fitView); }, []);   // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    let alive = true;
    loadStatus().then((m) => { if (alive) { setStatusMap(m); setLoaded(true); } });
    return () => { alive = false; };
  }, []);

  const setStatus = useCallback((num, st) => {
    setStatusMap((m) => {
      const next = { ...m, [num]: st };
      if (st === 'available') delete next[num];
      saveStatus(next);
      return next;
    });
  }, []);

  const matches = useMemo(() => {
    const q = search.trim();
    const lo = parseFloat(minA), hi = parseFloat(maxA);
    if (!q && isNaN(lo) && isNaN(hi) && statusFilter === 'all') return null;
    const s = new Set();
    PLOTS.forEach((p) => {
      if (q && !p.name.includes(q)) return;
      if (!isNaN(lo) && p.area < lo) return;
      if (!isNaN(hi) && p.area > hi) return;
      if (statusFilter !== 'all' && (status[p.name] || 'available') !== statusFilter) return;
      s.add(p.name);
    });
    return s;
  }, [search, minA, maxA, statusFilter, status]);

  const selPlot = selected ? BY_NAME.get(selected) : null;

  /**
   * Frame a plot into the part of the map the panel does not cover:
   * beside it on desktop, above it on phones. The plot you tapped is
   * therefore never hidden behind the panel that describes it.
   */
  const zoomTo = useCallback((plot) => {
    const phone = box.w <= 640;
    const panelW = box.w > 1024 ? 310 : 276;
    const fx = phone ? 0.5 : clamp((box.w - panelW) / (2 * box.w), 0.16, 0.5);
    const fy = phone ? 0.30 : 0.5;

    // the reference frames a selected plot at ~1.2-1.9x its own size; a little
    // wider keeps the neighbours visible without shrinking the type
    const span = Math.max(MIN_SPAN, Math.sqrt(plot.area) * (phone ? 2.6 : 2.2));
    const w = clamp(span, MIN_SPAN, MAX_SPAN);
    const h = w * aspect;
    setView({ x: plot.c[0] - fx * w, y: plot.c[1] - fy * h, w, h });
  }, [aspect, box.w]);

  const onSelect = (n) => {
    setSelected(n);
    if (n) zoomTo(BY_NAME.get(n));
  };

  const shown = matches ? matches.size : PLOTS.length;

  const inputStyle = {
    padding: '7px 10px', background: '#0D1117', color: '#EFEAE0',
    border: `1px solid ${HAIR}`, borderRadius: 7, fontFamily: MONO, fontSize: 16,
    outline: 'none', boxSizing: 'border-box', minWidth: 0,
  };

  return (
    <div style={{ width: '100%', height: '100dvh', minHeight: '100vh', position: 'relative',
      display: 'flex', flexDirection: 'column', background: CANVAS, color: '#E7E1D5',
      fontFamily: BODY, overflow: 'hidden' }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=Poppins:wght@400;500;600;700&display=swap');
        * { -webkit-tap-highlight-color: transparent; }
        input::placeholder { color: #5F6B78; }
        *:focus-visible { outline: 2px solid ${ACCENT}; outline-offset: 2px; }
        .toolbar { display: flex; align-items: center; gap: 8px; padding: 9px 14px;
          border-bottom: 1px solid ${HAIR}; flex-wrap: wrap; }
        .toolbar .spacer { margin-left: auto; }
        .toolbar-count { font-family: ${MONO}; font-size: 12px; color: ${MUTED}; }
        @media (max-width: 640px) {
          .toolbar { gap: 6px; padding: 8px 10px; overflow-x: auto; flex-wrap: nowrap;
            -webkit-overflow-scrolling: touch; }
          .toolbar > * { flex: 0 0 auto; }
          .toolbar .spacer { margin-left: 6px; }
          .toolbar .area-label { display: none; }
          .zoom-pad { bottom: calc(38vh + 16px) !important; }
        }
      `}</style>

      <div className="toolbar">
        <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Plot no."
          inputMode="numeric" style={{ ...inputStyle, width: 92 }} />
        <span className="area-label" style={{ color: MUTED, fontSize: 12, fontFamily: SANS,
          letterSpacing: '0.12em', textTransform: 'uppercase' }}>Area m²</span>
        <input value={minA} onChange={(e) => setMinA(e.target.value)} type="number" inputMode="decimal"
          placeholder={`${Math.floor(AREA_MIN)}`} style={{ ...inputStyle, width: 76 }} />
        <input value={maxA} onChange={(e) => setMaxA(e.target.value)} type="number" inputMode="decimal"
          placeholder={`${Math.ceil(AREA_MAX)}`} style={{ ...inputStyle, width: 76 }} />

        <Chip active={statusFilter === 'all'} onClick={() => setStatusFilter('all')}>All</Chip>
        {Object.entries(STATUS).map(([k, s]) => (
          <Chip key={k} active={statusFilter === k} swatch={s.dot}
            onClick={() => setStatusFilter(k)}>{s.label}</Chip>
        ))}

        <span className="spacer" />
        <span className="toolbar-count">{shown} / {PLOTS.length}</span>
        <Chip active={showNumbers} onClick={() => setShowNumbers((v) => !v)}>Numbers</Chip>
        <Chip onClick={() => { setSearch(''); setMinA(''); setMaxA(''); setStatusFilter('all'); }}>Clear</Chip>
        <Chip onClick={() => { setSelected(null); setView(fitView); }}>Fit plan</Chip>
      </div>

      <div ref={wrapRef} style={{ flex: 1, position: 'relative', minHeight: 0 }}>
        <PlanMap
          view={view} setView={setView}
          selected={selected} onSelect={onSelect}
          matches={matches} status={status} showNumbers={showNumbers}
        />

        <DetailPanel
          plot={selPlot} status={status} setStatus={setStatus}
          onClose={() => setSelected(null)}
          onQuote={() => setQuote(selPlot)}
        />
      </div>

      {quote && <Quotation plot={quote} onClose={() => setQuote(null)} onSave={saveQuotation} />}

      {!loaded && (
        <div style={{ position: 'absolute', inset: 0, display: 'grid', placeItems: 'center',
          background: CANVAS, color: MUTED, fontFamily: MONO, fontSize: 13, zIndex: 50 }}>
          Loading layout…
        </div>
      )}
    </div>
  );
}